-- Backfill workflow_definition and settings for seed workspaces (run after V7 if workspaces already existed).
-- Generated by scripts/generate-config-seed.mjs

DO $$
DECLARE
  v_org_id UUID;
BEGIN
  SELECT id INTO v_org_id FROM organizations WHERE slug = 'config-seed-org' LIMIT 1;
  IF v_org_id IS NULL THEN RETURN; END IF;

  UPDATE workspaces SET workflow_definition = '[{"type":"state","key":"NS","short":"NST","title":"Not Started","description":"Not yet started"},{"type":"milestone","key":"START","short":"GO","title":"Start","subtitle":"Project Kickoff"},{"type":"state","key":"DEV","short":"DEV","title":"Development","description":"In development"},{"type":"milestone","key":"M0","short":"M0","title":"Dev Complete","subtitle":"Development Finished"},{"type":"state","key":"VAL","short":"VAL","title":"Validation","description":"Under Technical Validation"},{"type":"milestone","key":"M1","short":"M1","title":"Val Complete","subtitle":"Validation Done"},{"type":"state","key":"ACC","short":"ACC","title":"Acceptance","description":"Acceptance Testing"},{"type":"milestone","key":"M2","short":"M2","title":"Production Ready","subtitle":"Ready for DTU consumption"},{"type":"state","key":"PRD","short":"PRD","title":"Parallel Run","description":"Parallel run 1.0 & 2.0"},{"type":"milestone","key":"M3","short":"M3","title":"Switch Complete","subtitle":"OneSource 1.0 Switch"},{"type":"state","key":"FIN","short":"FIN","title":"Finished","description":"Upgrade Completed"}]'::jsonb, settings = '{"start_month":"01/2026","end_month":"12/2026"}'::jsonb
  WHERE org_id = v_org_id AND slug = 'config';

  UPDATE workspaces SET workflow_definition = '[{"type":"state","key":"NS","short":"NS","title":"Not Started","description":"Not yet started"},{"type":"milestone","key":"A0","short":"A0","title":"Design Complete","subtitle":"Design Phase Done"},{"type":"state","key":"A0_S","short":"A0","title":"Design Complete","description":"Design Phase Done"},{"type":"milestone","key":"A1","short":"A1","title":"Dev Complete","subtitle":"Development Finished"},{"type":"state","key":"A1_S","short":"A1","title":"Dev Complete","description":"Development Finished"},{"type":"milestone","key":"A2","short":"A2","title":"QA Validated","subtitle":"Testing Passed"},{"type":"state","key":"A2_S","short":"A2","title":"QA Validated","description":"Testing Passed"},{"type":"milestone","key":"A3","short":"A3","title":"UAT Approved","subtitle":"User Acceptance"},{"type":"state","key":"A3_S","short":"A3","title":"UAT Approved","description":"User Acceptance"},{"type":"milestone","key":"A4","short":"A4","title":"Staging Ready","subtitle":"Pre-Production"},{"type":"state","key":"A4_S","short":"A4","title":"Staging Ready","description":"Pre-Production"},{"type":"milestone","key":"A5","short":"A5","title":"Production Live","subtitle":"Released to Prod"},{"type":"state","key":"A5_S","short":"A5","title":"Production Live","description":"Released to Prod"}]'::jsonb, settings = '{"start_month":"05/2025","end_month":"07/2026"}'::jsonb
  WHERE org_id = v_org_id AND slug = 'config-base';

  UPDATE workspaces SET workflow_definition = '[{"type":"state","key":"NS","short":"NST","title":"Not Started","description":"Not yet started"},{"type":"milestone","key":"START","short":"GO","title":"Start","subtitle":"Kickoff"},{"type":"state","key":"IP","short":"IP","title":"In Progress","description":"In progress"},{"type":"milestone","key":"M1","short":"M1","title":"Complete","subtitle":"Done"},{"type":"state","key":"DONE","short":"DONE","title":"Complete","description":"Completed"}]'::jsonb, settings = '{"start_month":"03/2026","end_month":"06/2026"}'::jsonb
  WHERE org_id = v_org_id AND slug = 'config-dsm';

  UPDATE workspaces SET workflow_definition = '[{"type":"state","key":"NS","short":"NST","title":"Not Started","description":"Not yet started"},{"type":"milestone","key":"START","short":"GO","title":"Start","subtitle":"Project Kickoff"},{"type":"state","key":"DEV","short":"DEV","title":"Development","description":"In development"},{"type":"milestone","key":"M0","short":"M0","title":"Dev Complete","subtitle":"Development Finished"},{"type":"state","key":"VAL","short":"VAL","title":"Validation","description":"Under Technical Validation"},{"type":"milestone","key":"M1","short":"M1","title":"Val Complete","subtitle":"Validation Done"},{"type":"state","key":"ACC","short":"ACC","title":"Acceptance","description":"Acceptance Testing"},{"type":"milestone","key":"M2","short":"M2","title":"Production Ready","subtitle":"Ready for DTU consumption"},{"type":"state","key":"PRD","short":"PRD","title":"Parallel Run","description":"Parallel run 1.0 & 2.0"},{"type":"milestone","key":"M3","short":"M3","title":"Switch Complete","subtitle":"OneSource 1.0 Switch"},{"type":"state","key":"FIN","short":"FIN","title":"Finished","description":"Upgrade Completed"}]'::jsonb, settings = '{"start_month":"01/2026","end_month":"09/2026"}'::jsonb
  WHERE org_id = v_org_id AND slug = 'config-onehouse-full';

  UPDATE workspaces SET workflow_definition = '[{"type":"state","key":"PRE","short":"PRE","title":"Pre-Migration","description":"Awaiting migration kick-off"},{"type":"milestone","key":"GO","short":"GO","title":"Start Migration","subtitle":"Migration Kick-off"},{"type":"state","key":"DEV_S","short":"DEV","title":"Under Development","description":"Active development in progress"},{"type":"milestone","key":"DEV","short":"DEV","title":"DEV Complete","subtitle":"Development Finished"},{"type":"state","key":"ACC","short":"UAT","title":"Under Acceptance","description":"QA validation & user acceptance testing"},{"type":"milestone","key":"UAT","short":"UAT","title":"UAT Passed","subtitle":"User Acceptance Testing Passed"},{"type":"state","key":"PROD_S","short":"PRD","title":"Production Deployment","description":"Scheduled deployment to production"},{"type":"milestone","key":"PROD","short":"PRD","title":"PROD Release","subtitle":"Released to Production"},{"type":"state","key":"PAR","short":"PAR","title":"Parallel Run","description":"Legacy & new systems running side-by-side"},{"type":"milestone","key":"FIN","short":"FIN","title":"Cutover Complete","subtitle":"Migration Complete – Legacy Decommissioned"},{"type":"state","key":"DONE","short":"DONE","title":"Migration Completed","description":"Fully migrated; legacy system retired"}]'::jsonb, settings = '{"start_month":"04/2026","end_month":"01/2027"}'::jsonb
  WHERE org_id = v_org_id AND slug = 'config-ple2';

  UPDATE workspaces SET workflow_definition = '[{"type":"state","key":"NS","short":"NS","title":"Not Started","description":"Planned, not yet kicked off"},{"type":"milestone","key":"KO","short":"KO","title":"Kickoff","subtitle":"Development Begins"},{"type":"state","key":"DEV","short":"DEV","title":"In Development","description":"Active development"},{"type":"milestone","key":"BETA","short":"β","title":"Beta","subtitle":"Feature Complete"},{"type":"state","key":"TST","short":"TST","title":"Testing","description":"Integration testing & review"},{"type":"milestone","key":"LIVE","short":"GO","title":"Live","subtitle":"Released to Production"},{"type":"state","key":"DONE","short":"DONE","title":"Done","description":"Shipped and stable"}]'::jsonb, settings = '{"start_month":"02/2026","end_month":"09/2027"}'::jsonb
  WHERE org_id = v_org_id AND slug = 'config-roadmapsnap';

END $$;
